import{_ as o,o as t,c as r,a2 as a}from"./chunks/framework.il0noOp3.js";const u=JSON.parse('{"title":"Changelog","description":"Release history and version changelog for AzureScout.","frontmatter":{"description":"Release history and version changelog for AzureScout."},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),n={name:"changelog.md"};function c(i,e,d,s,l,g){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>The full changelog is maintained in the repository root and rendered on GitHub.</p><p><a href="https://github.com/thisismydemo/azure-scout/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">View CHANGELOG.md on GitHub</a></p><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>AzureScout follows <a href="https://keepachangelog.com/en/1.1.0/" target="_blank" rel="noreferrer">Keep a Changelog</a> format and <a href="https://semver.org/spec/v2.0.0.html" target="_blank" rel="noreferrer">Semantic Versioning</a>.</p><table tabindex="0"><thead><tr><th>Version</th><th>Highlights</th></tr></thead><tbody><tr><td><strong>v2.2.0</strong> (2026-07-24)</td><td>Four new report tiers (<code>Word</code>, <code>EChartsDashboard</code>, <code>Pdf</code>, <code>JsonEvidence</code>), Excel visual dashboard tabs, a much richer interactive React report (topology, MG hierarchy, KPI cards, Governance section, drill-downs) + <code>report.pbit</code> generation, new offline analysis (<code>Get-ScoutInventoryDrift</code>, <code>Get-ScoutCostAnomaly</code>, <code>Get-ScoutIacGap</code>), IoT deep coverage (DPS + Digital Twins), tag aggregation, deeper Database/Analytics/IoT rule automation, collector/pipeline resilience, assessment config load/save (<code>Import-ScoutConfig</code>/<code>Export-ScoutConfig</code>), a CI pipeline, a real <code>azure-inventory</code> workflow, and five v1 inventory bug fixes</td></tr><tr><td><strong>v2.1.0</strong> (2026-07-23)</td><td>Native governance collector (<code>Import-Governance</code>, no more AzGovViz dependency by default), unattended one-command pipeline (<code>Invoke-ScoutPipeline</code>), and a React report + cross-run drift tracking (<code>-OutputFormat React</code>, <code>Get-ScoutDrift</code>)</td></tr><tr><td><strong>v2.0.0</strong></td><td><strong>CAF/WAF Assessment Platform</strong> — read-only assessment engine (139 rules across 8 CAF design areas + 5 WAF pillars), ARG collect layer, AzGovViz/Advisor/ARG ingest, ALZ benchmark, tiered reporting (Power BI / HTML / OpenXML PowerPoint / Excel / JSON), per-domain analytics via <code>Invoke-ScoutAssessment</code>. Runtime-verified offline + live tenant. Breaking: <code>findings.json</code> contract; assessment requires PowerShell 7</td></tr><tr><td><strong>v1.0.0</strong></td><td>Full rename to AzureScout (AZSC prefix), 154 ARM modules, 17 Entra ID modules, Excel + JSON + Markdown + AsciiDoc output, draw.io diagrams, permission pre-flight, category filtering</td></tr></tbody></table>',6)])])}const m=o(n,[["render",c]]);export{u as __pageData,m as default};
